import 'package:cloud_firestore/cloud_firestore.dart';

enum AppointmentStatus { booked, cancelled, completed }
class AppointmentModel { const AppointmentModel({required this.id, required this.studentId, required this.advisorId, required this.startsAt, required this.endsAt, this.status = AppointmentStatus.booked, this.consultationId}); final String id, studentId, advisorId; final DateTime startsAt, endsAt; final AppointmentStatus status; final String? consultationId; factory AppointmentModel.fromFirestore(DocumentSnapshot<Map<String,dynamic>> doc)=>AppointmentModel.fromMap(doc.id,doc.data() ?? const {}); factory AppointmentModel.fromMap(String id,Map<String,dynamic> map)=>AppointmentModel(id:id,studentId:map['studentId'] as String? ?? '',advisorId:map['advisorId'] as String? ?? '',startsAt:(map['startsAt'] as Timestamp?)?.toDate() ?? DateTime.now(),endsAt:(map['endsAt'] as Timestamp?)?.toDate() ?? DateTime.now(),status:AppointmentStatus.values.firstWhere((item)=>item.name==map['status'],orElse:()=>AppointmentStatus.booked),consultationId:map['consultationId'] as String?); Map<String,Object?> toMap()=>{'studentId':studentId,'advisorId':advisorId,'startsAt':Timestamp.fromDate(startsAt),'endsAt':Timestamp.fromDate(endsAt),'status':status.name,'consultationId':consultationId,'updatedAt':FieldValue.serverTimestamp()}; }
